args.content:
SELECT ?item ?itemLabel ?coord
WHERE {
  ?item wdt:P31 wd:Q5701163.  # point of interest
  ?item wdt:P17 wd:Q29.      # located in Spain
  ?item wdt:P625 ?coord.     # coordinate property
  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en".
  }
}

